1	/**
2	 * 街头随机事件数据（从 events.js 拆分）
3	 *
4	 * 自动推入 RANDOM_EVENTS 数组。
5	 * 必须在 events_core.js 之后加载。
6	 */
7	
8	(function () {
9	  if (typeof RANDOM_EVENTS === "undefined") return;
10	  if (RANDOM_EVENTS._streetLoaded) return;
11	  RANDOM_EVENTS._streetLoaded = true;
12	  var EVENTS = [
13	    {
14	      id: "found_wallet",
15	      phase: "street",
16	      icon: "👛",
17	      title: "捡到了一个钱包",
18	      story:
19	        "路边有个黑色钱包，打开一看里面有一叠现金和一张身份证。失主看起来住在附近。",
20	      choices: [
21	        {
22	          text: "💰 据为己有",
23	          hint: "拿钱走人",
24	          apply: (st) => {
25	            const cash = 80 + Math.floor(Math.random() * 200);
26	            st.resources.cash += cash;
27	            st.needs.happiness = Math.max(0, st.needs.happiness - 8);
28	            st.flags._keptWallet = true;
29	            StateManager.addMessage(
30	              `💰 钱包里翻出了 ¥${cash}，但心里有点虚...`,
31	              "warning",
32	            );
33	          },
34	        },
35	        {
36	          text: "🏛️ 交给派出所",
37	          hint: "良心选择",
38	          apply: (st) => {
39	            st.needs.happiness = Math.min(100, st.needs.happiness + 12);
40	            st.player.fame = Math.min(100, st.player.fame + 3);
41	            st.flags._returnedWallet = true;
42	            StateManager.addMessage(
43	              "🏛️ 钱包交给了警察，警察夸你拾金不昧，心情大好！",
44	              "success",
45	            );
46	          },
47	        },
48	        {
49	          text: "🚶 当作没看见",
50	          hint: "怕惹麻烦",
51	          apply: (st) => {
52	            // 啥也不发生
53	            StateManager.addMessage("🚶 你假装没看见走了过去。", "info");
54	          },
55	        },
56	      ],
57	    },
58	    {
59	      id: "street_mugging",
60	      phase: "street",
61	      icon: "😱",
62	      title: "遇到小混混敲诈",
63	      story:
64	        "几个小混混拦住你，说最近手头紧，要借点钱花花。对方有 3 个人，你孤身一人。",
65	      conditions: (st) => st.resources.cash >= 50,
66	      choices: [
67	        {
68	          text: "💸 破财消灾 (¥80)",
69	          hint: "认怂保平安",
70	          cost: 80,
71	          apply: (st) => {
72	            st.resources.cash = Math.max(0, st.resources.cash - 80);
73	            st.needs.happiness = Math.max(0, st.needs.happiness - 15);
74	            StateManager.addMessage(
75	              "💸 给了 80 块，混混笑着走了。心里憋屈。",
76	              "warning",
77	            );
78	          },
79	        },
80	        {
81	          text: "🏃 撒腿就跑",
82	          hint: "考验敏捷",
83	          apply: (st) => {
84	            if (Math.random() < 0.5 + (st.player.agility - 20) * 0.02) {
85	              StateManager.addMessage(
86	                "🏃 你转身就跑，甩开了混混，逃过一劫！",
87	                "success",
88	              );
89	            } else {
90	              st.status.injured = true;
91	              st.status.health = Math.max(0, st.status.health - 20);
92	              st.resources.cash = Math.max(0, st.resources.cash - 100);
93	              StateManager.addMessage(
94	                "🏃 没跑掉，挨了一顿拳脚，被抢了 100 块！",
95	                "danger",
96	              );
97	            }
98	          },
99	        },
100	        {
101	          text: "📱 假装打电话报警",
102	          hint: "虚张声势",
103	          apply: (st) => {
104	            if (Math.random() < 0.4) {
105	              st.needs.happiness = Math.min(100, st.needs.happiness + 5);
106	              StateManager.addMessage(
107	                "📱 混混看你报警，一哄而散。你真聪明！",
108	                "success",
109	              );
110	            } else {
111	              st.resources.cash = Math.max(0, st.resources.cash - 50);
112	              st.needs.happiness = Math.max(0, st.needs.happiness - 5);
113	              StateManager.addMessage(
114	                "📱 被识破了！还是被抢了 50 块，混混也走了。",
115	                "warning",
116	              );
117	            }
118	          },
119	        },
120	      ],
121	    },
122	    {
123	      id: "stranger_invest",
124	      phase: "street",
125	      icon: "💹",
126	      title: "陌生人推荐「内部消息」",
127	      story:
128	        "一个穿西装的人凑过来，神神秘秘地说他知道一只股票的内幕消息，明天必涨，现在买入稳赚。",
129	      choices: [
130	        {
131	          text: "💰 信了，押 ¥500",
132	          hint: "赌一把",
133	          apply: (st) => {
134	            if (st.resources.cash < 500) {
135	              StateManager.addMessage(
136	                "💰 现金不足 500，错失良机（坑）",
137	                "warning",
138	              );
139	              return;
140	            }
141	            st.resources.cash -= 500;
142	            // 50% 概率赚一倍，50% 概率打水漂
143	            if (Math.random() < 0.4) {
144	              const profit = 300 + Math.floor(Math.random() * 400);
145	              st.resources.cash += profit;
146	              StateManager.addMessage(
147	                `💰 消息是真的！赚了 ¥${profit - 500}。`,
148	                "success",
149	              );
150	            } else {
151	              StateManager.addMessage(
152	                "💰 假消息！500 块打了水漂，人也跑了。",
153	                "danger",
154	              );
155	            }
156	          },
157	        },
158	        {
159	          text: "🚶 礼貌拒绝走人",
160	          hint: "理性选择",
161	          apply: (st) => {
162	            StateManager.addMessage(
163	              "🚶 你礼貌地摆摆手走开了。天上不会掉馅饼。",
164	              "info",
165	            );
166	          },
167	        },
168	        {
169	          text: "📱 反手举报给警察",
170	          hint: "正义感",
171	          apply: (st) => {
172	            st.player.fame = Math.min(100, st.player.fame + 5);
173	            st.needs.happiness = Math.min(100, st.needs.happiness + 6);
174	            StateManager.addMessage(
175	              "📱 警察抓到了诈骗团伙，给你点了个赞！",
176	              "success",
177	            );
178	          },
179	        },
180	      ],
181	    },
182	    {
183	      id: "old_man_help",
184	      phase: "street",
185	      icon: "👴",
186	      title: "老大爷需要帮助",
187	      story:
188	        "路边一位老大爷拎着两袋米，气喘吁吁地站在那儿。他想让你帮忙把米送回家，就在附近。",
189	      choices: [
190	        {
191	          text: "🤝 帮忙送米",
192	          hint: "可能有好报",
193	          apply: (st) => {
194	            st.needs.fatigue = Math.min(100, st.needs.fatigue + 12);
195	            if (Math.random() < 0.5) {
196	              const reward = 50 + Math.floor(Math.random() * 80);
197	              st.resources.cash += reward;
198	              st.player.fame = Math.min(100, st.player.fame + 2);
199	              st.needs.happiness = Math.min(100, st.needs.happiness + 10);
200	              // 类似老周的性格，帮忙后老周好感微量提升
201	              if (st.relationships && st.relationships["old_zhou"]) {
202	                st.relationships["old_zhou"].affinity = Math.min(
203	                  100,
204	                  st.relationships["old_zhou"].affinity + 1,
205	                );
206	              }
207	              StateManager.addMessage(
208	                `🤝 老大爷非要给你 ¥${reward}，还夸你是个好孩子！`,
209	                "success",
210	              );
211	            } else {
212	              st.needs.happiness = Math.min(100, st.needs.happiness + 5);
213	              StateManager.addMessage(
214	                "🤝 把米送到了，大爷连声道谢。虽然没给钱，但心里暖暖的。",
215	                "success",
216	              );
217	            }
218	          },
219	        },
220	        {
221	          text: "🚶 装作赶时间走开",
222	          hint: "爱莫能助",
223	          apply: (st) => {
224	            st.needs.happiness = Math.max(0, st.needs.happiness - 3);
225	            StateManager.addMessage("🚶 你低着头快步走开了。", "info");
226	          },
227	        },
228	      ],
229	    },
