231	      id: "free_clinic",
232	      phase: "street",
233	      icon: "💊",
234	      title: "街头免费义诊",
235	      story:
236	        "社区在广场办免费义诊活动。志愿者医生说你最近看起来气色不好，可以免费做个基础检查。",
237	      choices: [
238	        {
239	          text: "🩺 接受检查",
240	          hint: "了解身体状况",
