243	            if (st.status.sick) {
244	              st.status.sick = false;
245	              st.status.health = Math.min(100, st.status.health + 20);
246	              StateManager.addMessage(
247	                "🩺 医生发现你在生病，免费开了药！病好了，健康+20。",
248	                "success",
249	              );
250	            } else if (st.status.injured) {
251	              st.status.injured = false;
252	              st.status.health = Math.min(100, st.status.health + 15);
253	              StateManager.addMessage(
254	                "🩺 医生处理了你的伤口，上了点药。健康+15。",
255	                "success",
256	              );
257	            } else {
258	              st.status.health = Math.min(100, st.status.health + 5);
259	              st.needs.happiness = Math.min(100, st.needs.happiness + 5);
260	              StateManager.addMessage(
261	                "🩺 一切正常！医生夸你身体不错，心情也好了。",
262	                "success",
263	              );
264	            }
265	          },
266	        },
267	        {
268	          text: "🚶 没空，继续忙",
269	          hint: "省时间",
270	          apply: (st) => {
271	            StateManager.addMessage("🚶 你摇摇头继续忙自己的事了。", "info");
272	          },
273	        },
274	      ],
275	    },
276	    {
277	      id: "thrift_find",
278	      phase: "street",
279	      icon: "🛍️",
280	      title: "二手店捡漏",
281	      story:
282	        "路过一家二手店，老板说今天清仓，全场 5 折！你注意到有件还不错的东西。",
283	      choices: [
284	        {
285	          text: "🛍️ 买本技能书 (¥50)",
286	          hint: "可能加技能",
287	          cost: 50,
288	          apply: (st) => {
