301	          },
302	        },
303	        {
304	          text: "🧥 淘件二手衣服 (¥30)",
305	          hint: "提升卫生/心情",
306	          cost: 30,
307	          apply: (st) => {
308	            if (st.resources.cash < 30) {
309	              StateManager.addMessage("🧥 钱不够买！", "warning");
310	              return;
311	            }
312	            st.resources.cash -= 30;
313	            st.needs.hygiene = Math.min(100, st.needs.hygiene + 15);
314	            st.needs.happiness = Math.min(100, st.needs.happiness + 8);
