316	              "🧥 买到了件干净的旧衣服，焕然一新！",
317	              "success",
318	            );
319	          },
320	        },
321	        {
322	          text: "🚶 啥都不需要",
323	          hint: "理性消费",
324	          apply: (st) => {
325	            StateManager.addMessage("🚶 家里啥都不缺，看看就好。", "info");
326	          },
327	        },
328	      ],
329	    },
