331	      id: "neighbor_fight",
332	      phase: "street",
333	      icon: "🤼",
334	      title: "邻居吵架请你评理",
335	      story: "楼上的两口子又在吵架，女方哭着跑下来向你诉苦。男的说她无理取闹。",
336	      choices: [
337	        {
338	          text: "🫂 安慰女方 (听听她说话)",
339	          hint: "提升好感",
340	          apply: (st) => {
341	            st.needs.happiness = Math.min(100, st.needs.happiness - 5);
342	            st.needs.fatigue = Math.min(100, st.needs.fatigue + 5);
