347	          },
348	        },
349	        {
350	          text: "🧠 理智劝和",
351	          hint: "考验智力",
352	          apply: (st) => {
353	            if (Math.random() < 0.4 + (st.player.intelligence - 20) * 0.02) {
354	              st.needs.happiness = Math.min(100, st.needs.happiness + 10);
355	              st.player.fame = Math.min(100, st.player.fame + 3);
356	              StateManager.addMessage(
357	                "🧠 你一番话说得两人都服气了，握手言和！还夸你通情达理。",
358	                "success",
359	              );
360	            } else {
361	              st.needs.happiness = Math.max(0, st.needs.happiness - 8);
362	              StateManager.addMessage(
363	                "🧠 你越劝越乱，两口子矛头转向了你...赶紧溜。",
364	                "warning",
365	              );
366	            }
367	          },
368	        },
369	        {
370	          text: "🚶 装作没听见",
371	          hint: "管闲事",
372	          apply: (st) => {
373	            StateManager.addMessage("🚶 你戴上耳机假装没听见。", "info");
374	          },
375	        },
376	      ],
377	    },
378	    {
379	      id: "lost_pet",
380	      phase: "street",
381	      icon: "🐕",
382	      title: "走失的小狗",
383	      story:
384	        "一只脏兮兮的小狗跟着你，可怜巴巴的。它脖子上有项圈但没联系方式，看着已经流浪几天了。",
385	      choices: [
386	        {
387	          text: "🏠 收养它",
388	          hint: "需要花钱照顾",
389	          apply: (st) => {
390	            st.resources.cash = Math.max(0, st.resources.cash - 30);
391	            st.needs.happiness = Math.min(100, st.needs.happiness + 20);
392	            st.needs.fatigue = Math.max(0, st.needs.fatigue - 5);
393	            st.player.fame = Math.min(100, st.player.fame + 1);
394	            StateManager.addMessage(
395	              "🐕 收养了一只小狗！花了 30 块买了狗粮，心情大好！疲劳-5。",
396	              "success",
397	            );
398	            // 标记有宠物
399	            st.flags.hasPet = true;
400	          },
401	        },
402	        {
403	          text: "📞 帮它找主人",
404	          hint: "贴寻狗启事",
405	          apply: (st) => {
406	            st.needs.fatigue = Math.min(100, st.needs.fatigue + 8);
407	            st.player.fame = Math.min(100, st.player.fame + 2);
408	            StateManager.addMessage(
409	              "📞 主人找到了！你好人有好报，心情不错。",
410	              "success",
411	            );
412	          },
413	        },
414	        {
415	          text: "🚶 爱莫能助",
416	          hint: "没办法",
417	          apply: (st) => {
418	            st.needs.happiness = Math.max(0, st.needs.happiness - 3);
419	            StateManager.addMessage(
420	              "🚶 你狠心走开了...希望它能自己找到家。",
421	              "info",
422	            );
423	          },
424	        },
425	      ],
426	    },
427	    {
428	      id: "real_estate_rumour",
429	      phase: "street",
430	      icon: "🏗️",
431	      title: "楼盘烂尾传闻",
432	      story:
433	        "在城中村听到几个工友议论，说城郊那个新楼盘'锦绣豪庭'开发商资金链断了，可能要烂尾。不少购房者已经交了首付。有人说开发商正在秘密转让项目。",
434	      choices: [
435	        {
436	          text: "👂 多打听点消息 (花¥30请人吃饭)",
437	          hint: "需要情报",
438	          cost: 30,
439	          apply: (st) => {
440	            if (st.resources.cash < 30) {
441	              StateManager.addMessage("👂 钱不够，先攒点再说。", "warning");
