444	            st.resources.cash -= 30;
445	            st.needs.happiness = Math.min(100, st.needs.happiness + 3);
446	            // 调度后续事件：内幕消息
447	            if (typeof scheduleChainEvent === "function") {
448	              scheduleChainEvent(st, "real_estate_insider", 2, "street");
449	            }
450	            StateManager.addMessage(
451	              "👂 请几个工友吃了顿饭，他们透露：开发商老板已经出国了，项目可能被低价转让。",
452	              "info",
453	            );
454	          },
455	        },
456	        {
457	          text: "🏠 去看看楼盘情况",
458	          hint: "实地考察",
459	          apply: (st) => {
