466	            StateManager.addMessage(
467	              "🏠 去工地转了一圈，确实停工了，几个保安说开发商已经两个月没发工资。",
468	              "info",
469	            );
470	          },
471	        },
472	        {
473	          text: "🚶 关我啥事，走人",
474	          hint: "明哲保身",
475	          apply: (st) => {
476	            StateManager.addMessage(
477	              "🚶 你摇摇头走开了。房地产的事太复杂，还是不掺和。",
478	              "info",
479	            );
480	          },
481	        },
482	      ],
483	    },
484	    {
485	      id: "real_estate_insider",
486	      phase: "street",
487	      icon: "🎲",
488	      title: "内幕消息：赌局来了",
489	      story:
490	        "一个自称是开发商前财务的人找到你，说他知道一个内幕：项目下周会被一家小房企低价收购，收购消息一旦公布，相关股票会暴涨。他让你帮忙凑钱买股票，事成之后分你三成利润。但风险是：如果消息是假的，或者收购失败，钱就全砸里面了。对方要求你至少投入¥2000。",
491	      choices: [
492	        {
493	          text: "💰 全押进去 (¥2000+)",
494	          hint: "高风险高回报",
495	          cost: 2000,
496	          apply: (st) => {
497	            if (st.resources.cash < 2000) {
498	              StateManager.addMessage(
499	                "💰 现金不足2000，只能遗憾错过。",
500	                "warning",
501	              );
502	              return;
503	            }
504	            st.resources.cash -= 2000;
505	            // 60% 概率成功：收购消息公布，股票翻倍
506	            // 40% 概率失败：消息是假的/收购失败
507	            const success = Math.random() < 0.6;
508	            if (success) {
509	              const profit = 2000 + Math.floor(Math.random() * 1500) + 500;
510	              st.resources.cash += profit;
511	              st.player.fame = Math.min(100, st.player.fame + 5);
512	              st.needs.happiness = Math.min(100, st.needs.happiness + 15);
513	              // 标记已参与赌局成功
514	              st.flags._realEstateGambleWon = true;
515	              StateManager.addMessage(
516	                `💰 收购消息公布，股票暴涨！你赚了 ¥${profit - 2000}！这内幕消息真准！`,
517	                "success",
518	              );
519	              // 调度后续：财富膨胀的代价
